class Doc:
    def __init__(self):
        self._text = ''
        self._done = []   # steps that can be undone; each step is a list of edits
        self._undone = []  # steps that can be redone
        self._open = []   # stack of currently open groups (lists of edits)

    def text(self):
        return self._text

    def begin_group(self):
        self._open.append([])

    def end_group(self):
        if not self._open:
            raise RuntimeError('end_group without matching begin_group')
        group = self._open.pop()
        if self._open:
            # Nested group: its edits merge into the enclosing group.
            self._open[-1].extend(group)
        elif group:
            # Only the outermost pair forms a step.
            self._done.append(group)
            self._undone.clear()

    def _apply(self, edit):
        kind, pos, s = edit
        if kind == 'insert':
            self._text = self._text[:pos] + s + self._text[pos:]
        else:
            self._text = self._text[:pos] + self._text[pos + len(s):]

    def _invert(self, edit):
        kind, pos, s = edit
        return ('delete' if kind == 'insert' else 'insert', pos, s)

    def _record(self, edit):
        if self._open:
            self._open[-1].append(edit)
        else:
            self._done.append([edit])
        # A new edit discards the steps that could still have been redone.
        self._undone.clear()

    def insert(self, pos, s):
        if pos < 0 or pos > len(self._text):
            raise IndexError(pos)
        edit = ('insert', pos, s)
        self._apply(edit)
        self._record(edit)

    def delete(self, pos, n):
        if pos < 0 or n < 0 or pos + n > len(self._text):
            raise IndexError(pos)
        edit = ('delete', pos, self._text[pos:pos + n])
        self._apply(edit)
        self._record(edit)

    def undo(self):
        if self._open:
            raise RuntimeError('undo while a group is open')
        if not self._done:
            return
        step = self._done.pop()
        for edit in reversed(step):
            self._apply(self._invert(edit))
        self._undone.append(step)

    def redo(self):
        if self._open:
            raise RuntimeError('redo while a group is open')
        if not self._undone:
            return
        step = self._undone.pop()
        for edit in step:
            self._apply(edit)
        self._done.append(step)

